// POST GIG
//////////////////////////////////////////////////////

import { cookies } from "next/headers";

export async function POST(req: Request) {
    const ip = (req.headers.get("x-forwarded-for") || "unknown").split(",")[0].trim();
    if (!(await generalApiLimiter.check(ip))) {
        return NextResponse.json({ error: "Too many requests" }, { status: 429 });
    }
    try {
        const cookieStore = await cookies();
        const isPreview = (await cookieStore).get('admin_preview_mode')?.value === 'true';

        if (isPreview) {
            return NextResponse.json({ error: "Cannot post gigs in Preview Mode" }, { status: 403 });
        }
        const supabase = await createClient();
        const { data: { user }, error } =
            await supabase.auth.getUser();

        if (error || !user) {
            return NextResponse.json(
                { error: "Unauthorized" },
                { status: 401 }
            );
        }

        // ðŸ›¡ï¸ UUID Guard â€” prevent P2023 from invalid Supabase user IDs
        try {
            validateSessionUserId(user.id, "POST /api/gigs");
        } catch (uuidErr) {
            console.error("[P2023 Guard]", uuidErr);
            return NextResponse.json({ error: "Invalid session identity. Please sign out and sign in again." }, { status: 400 });
        }

        const body = await req.json();

        // Zod Validation
        const parseResult = GigCreateSchema.safeParse(body);
        if (!parseResult.success) {
            return NextResponse.json(
                { error: "Validation failed", details: parseResult.error.flatten().fieldErrors },
                { status: 400 }
            );
        }

        const {
            budget,
            deadline,
        } = parseResult.data;

        const title = sanitizeInput(parseResult.data.title);
        const description = sanitizeInput(parseResult.data.description);

        //////////////////////////////////////////////////////
        // AUTO CREATE PROFILE IF MISSING â­ FIX
        //////////////////////////////////////////////////////

        let dbUser = await prisma.user.findUnique({
            where: { id: user.id },
        });

        if (!dbUser) {
            dbUser = await prisma.user.create({
                data: {
                    id: user.id,
                    email: user.email!,
                },
            });
        }

        //////////////////////////////////////////////////////
        // AI CONTENT MODERATION
        //////////////////////////////////////////////////////

        const modResult = await moderateGig(title, description, dbUser.id);
        if (modResult.autoReject) {
            return NextResponse.json(
                { error: `Your gig was automatically rejected: ${modResult.reason}` },
                { status: 422 }
            );
        }

        // Flagged content goes to pending admin review, safe content auto-approves
        const initialStatus = modResult.action === 'FLAG' ? 'PENDING_APPROVAL' : 'OPEN';

        //////////////////////////////////////////////////////
        // CREATE GIG
        //////////////////////////////////////////////////////

        const gig = await prisma.gig.create({
            data: {
                title,
                description,
                budget: Number(budget),
                deadline,
                posted_by: dbUser.id,
                status: initialStatus,
                latitude: dbUser.latitude,
                longitude: dbUser.longitude,
            },
        });

        // Pre-compute gig vector embedding asynchronously in the background (fire-and-forget)
        import("@/lib/ai/embeddings").then(({ computeGigEmbedding }) => {
            computeGigEmbedding(gig.id).catch(err => {
                console.error("[GIGS_POST] Asynchronous embedding update failed:", err);
            });
        });

        // NOTIFICATIONS: Notify followers
        // Note: Using try-catch to prevent blocking the response if notification fails
        try {
            const followers = await prisma.follows.findMany({
                where: { followingId: dbUser.id },
                select: { followerId: true }
            });

            if (followers.length > 0) {
                await prisma.notification.createMany({
                    data: followers.map((f: any) => ({
                        userId: f.followerId,
                        type: "FOLLOW_ACTIVITY",
                        title: "New Post from Network",
                        message: `${dbUser.name || "A connection"} posted a new gig: ${title}`,
                        link: `/gigs/${gig.id}`
                    }))
                });
            }
        } catch (notifError) {
            console.error("Failed to send notifications:", notifError);
        }

        return NextResponse.json(gig, {
            status: 201,
        });
    } catch (error: unknown) {
        const msg = error instanceof Error ? error.message : "Internal server error";
        console.error("[GIGS_POST_ERROR]:", error);
        return NextResponse.json(
            { error: msg },
            { status: 500 }
        );
    }
}

// PATCH - Update Gig status (e.g. mark as completed)
export async function PATCH(req: Request) {
    try {
        const supabase = await createClient();
        const { data: { user } } = await supabase.auth.getUser();
        if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

        const body = await req.json();

        // Zod Validation
        const parseResult = GigPatchSchema.safeParse(body);
        if (!parseResult.success) {
            return NextResponse.json(
                { error: "Validation failed", details: parseResult.error.flatten().fieldErrors },
                { status: 400 }
            );
        }

        const { id, status } = parseResult.data;

        const gig = await prisma.gig.findUnique({ where: { id } });
        if (!gig) return NextResponse.json({ error: "Gig not found" }, { status: 404 });

        // Only poster or founder
        if (gig.posted_by !== user.id) {
            const dbUser = await prisma.user.findUnique({ where: { id: user.id }, select: { role: true } });
            if (dbUser?.role !== "FOUNDER") {
                return NextResponse.json({ error: "Forbidden" }, { status: 403 });
            }
        }

        const completedAt = status === "COMPLETED" ? new Date() : null;

        const updated = await prisma.gig.update({
            where: { id },
            data: { 
                status,
                completedAt
            }
        });

        return NextResponse.json(updated);
    } catch (error) {
        console.error("[GIGS_PATCH_ERROR]", error);
        return NextResponse.json({ error: "Internal server error" }, { status: 500 });
    }
}

// DELETE - Remove a gig
export async function DELETE(req: Request) {
    try {
        const supabase = await createClient();
        const { data: { user } } = await supabase.auth.getUser();
        if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

        const { searchParams } = new URL(req.url);
        const id = searchParams.get("id");
        if (!id) return NextResponse.json({ error: "ID required" }, { status: 400 });

        // UUID Guard
        if (!z.string().uuid().safeParse(id).success) {
            return NextResponse.json({ error: "Invalid ID format" }, { status: 400 });
        }

        const gig = await prisma.gig.findUnique({ where: { id } });
        if (!gig) return NextResponse.json({ error: "Gig not found" }, { status: 404 });

        if (gig.posted_by !== user.id) {
            const dbUser = await prisma.user.findUnique({ where: { id: user.id }, select: { role: true } });
            if (dbUser?.role !== "FOUNDER") {
                return NextResponse.json({ error: "Forbidden" }, { status: 403 });
            }
        }

        await prisma.gig.delete({ where: { id } });
        return NextResponse.json({ success: true });
    } catch (error) {
        console.error("[GIGS_DELETE_ERROR]", error);
        return NextResponse.json({ error: "Internal server error" }, { status: 500 });
    }
}

import { NextRequest, NextResponse } from "next/server";

import { getSession } from "@/lib/auth-checks";
import prisma from "@/lib/prisma";
import { razorpay } from "@/lib/razorpay";

export async function POST(req: NextRequest) {
    try {
        const user = await getSession();
        if (!user || (user.role !== "CLIENT" && user.role !== "STARTUP" && user.role !== "FOUNDER")) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const { gigId, workerId } = await req.json();
        if (!gigId || !workerId) {
            return NextResponse.json({ error: "gigId and workerId are required" }, { status: 400 });
        }

        // Validate Gig
        const gig = await prisma.gig.findUnique({ where: { id: gigId } });
        if (!gig) return NextResponse.json({ error: "Gig not found" }, { status: 404 });
        if (gig.posted_by !== user.id) return NextResponse.json({ error: "Unauthorized. You are not the gig poster." }, { status: 403 });

        // Calculate amount (Budget + 10% Platform Fee)
        const budget = gig.budget;
        const platformFee = budget * 0.10;
        const totalAmount = budget + platformFee;

        // Razorpay expects amount in paise (1 INR = 100 paise)
        const amountInPaise = Math.round(totalAmount * 100);

        // Generate Razorpay Order
        const options = {
            amount: amountInPaise,
            currency: "INR",
            receipt: `escrow_${gigId.slice(0, 8)}_${Date.now()}`,
            notes: {
                gigId,
                clientId: user.id,
                workerId,
            }
        };

        const order = await razorpay.orders.create(options);

        if (!order || !order.id) {
            throw new Error("Failed to create Razorpay order");
        }

        // Atomically Create Transaction and Escrow in PENDING state
        await prisma.$transaction(async (tx: any) => {
            const _escrow = await tx.escrow.create({
                data: {
                    gigId,
                    clientId: user.id,
                    workerId,
                    amount: totalAmount,
                    platformFee,
                    payout: budget, // The worker gets the budget
                    commissionRate: 0.10,
                    status: "PENDING"
                }
            });

            await tx.transaction.create({
                data: {
                    gigId,
                    buyerId: user.id,
                    sellerId: workerId,
                    amount: totalAmount,
                    platformFee,
                    sellerPayout: budget,
                    paymentProvider: "Razorpay",
                    paymentId: order.id, // We store order_id here temporarily until verified
                    status: "PENDING",
                    description: `Escrow lock for Gig: ${gig.title}`,
                }
            });
        });

        return NextResponse.json({ orderId: order.id, amount: totalAmount, key: process.env.NEXT_PUBLIC_RAZORPAY_KEY_ID });
    } catch (error: any) {
        console.error("[CREATE_ORDER_ERROR]", error);
        return NextResponse.json({ error: error.message || "Internal server error" }, { status: 500 });
    }
}

import { NextRequest, NextResponse } from "next/server";

// Server refresh
import { z } from "zod";

import prisma from "@/lib/prisma";
import { sanitizeInput } from "@/lib/security/sanitization";
import { createClient } from "@/lib/supabase/server";


const ReviewSchema = z.object({
    gigId: z.string().uuid("Invalid Gig ID format"),
    revieweeId: z.string().uuid("Invalid Reviewee ID format"),
    rating: z.number().min(1, "Minimum rating is 1").max(5, "Maximum rating is 5"),
    comment: z.string().max(1000, "Comment must be under 1000 characters").optional().nullable(),
});

export async function POST(req: NextRequest) {
    try {
        const supabase = await createClient();
        const { data: { user }, error } = await supabase.auth.getUser();

        if (error || !user) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        let body;
        try {
            body = await req.json();
        } catch {
            return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
        }

        const parseResult = ReviewSchema.safeParse(body);
        if (!parseResult.success) {
            return NextResponse.json(
                { error: "Validation failed", details: parseResult.error.flatten().fieldErrors },
                { status: 400 }
            );
        }

        const { gigId, revieweeId, rating } = parseResult.data;
        const comment = parseResult.data.comment ? sanitizeInput(parseResult.data.comment) : null;

        if (user.id === revieweeId) {
            return NextResponse.json({ error: "Cannot review yourself" }, { status: 400 });
        }

        // Verify gig exists and is completed
        const gig = await prisma.gig.findUnique({
            where: { id: gigId },
            include: { applications: { where: { status: "ACCEPTED" } }, poster: true }
        });

        if (!gig) return NextResponse.json({ error: "Gig not found" }, { status: 404 });
        if (gig.status !== "COMPLETED") return NextResponse.json({ error: "Gig is not completed yet" }, { status: 400 });

        // Ensure user is involved in the gig
        const acceptedApp = gig.applications[0];
        if (!acceptedApp) return NextResponse.json({ error: "No accepted application" }, { status: 400 });

        const isClient = gig.posted_by === user.id;
        const isWorker = acceptedApp.applicantId === user.id;

        if (!isClient && !isWorker) {
            return NextResponse.json({ error: "You are not involved in this gig" }, { status: 403 });
        }

        // Verify that the reviewee is indeed the other party
        if (isClient && revieweeId !== acceptedApp.applicantId) {
            return NextResponse.json({ error: "You can only review the student who completed the gig" }, { status: 400 });
        }

        if (isWorker && revieweeId !== gig.posted_by) {
            return NextResponse.json({ error: "You can only review the client of the gig" }, { status: 400 });
        }

        const review = await prisma.review.create({
            data: {
                gigId,
                reviewerId: user.id,
                revieweeId,
                rating: Number(rating),
                comment,
            }
        });

        // Notify reviewee
        await prisma.notification.create({
            data: {
                userId: revieweeId,
                title: "New Review Received",
                message: `You received a ${rating}-star review for your work on "${gig.title}".`,
                type: "REVIEW",
                link: "/profile"
            }
        });

        return NextResponse.json({ success: true, review });
    } catch (error: unknown) {
        console.error("Review error:", error);
        return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
    }
}

