                                                    <div className="w-1 h-1 rounded-full bg-white animate-pulse" />
                                                    {skill}
                                                </Badge>
                                            </motion.div>
                                        ))}
                                    </div>
                                </div>

                                {/* Suggestions */}
                                <Card className="border-white/5 bg-[#111827] shadow-3xl rounded-5xl overflow-hidden relative group">
                                    <div className="absolute top-0 right-0 w-64 h-64 bg-orange-500/10 blur-[100px] pointer-events-none" />
                                    <CardContent className="p-10">
                                        <h4 className="font-black text-white mb-8 flex items-center gap-4">
                                            <Star className="text-amber-400 fill-amber-400 drop-shadow-[0_0_10px_rgba(251,191,36,0.6)]" size={32} /> 
                                            Strategic Battle Plan
                                        </h4>
                                        <div className="space-y-6">
                                            {result?.suggestions?.map((sug, idx) => (
                                                <motion.div 
                                                    key={idx} 
                                                    className="flex gap-6 group/item"
                                                    initial={{ opacity: 0, y: 10 }}
                                                    animate={{ opacity: 1, y: 0 }}
                                                    transition={{ delay: 0.6 + idx * 0.1 }}
                                                >
                                                    <div className="w-10 h-10 rounded-2xl bg-orange-500/10 flex items-center justify-center font-black text-orange-400 shrink-0 border border-white/5 group-hover/item:bg-orange-600 group-hover/item:text-white group-hover/item:scale-110 transition-all duration-300">
                                                        {idx + 1}
                                                    </div>
                                                    <div className="space-y-1 pt-1">
                                                       <p className="text-base leading-relaxed font-bold group-hover/item:text-white transition-colors">
                                                          {sug}
                                                       </p>
                                                    </div>
                                                </motion.div>
                                            ))}
                                        </div>
                                    </CardContent>
                                </Card>
                            </motion.div>
                        )}
                    </AnimatePresence>
                </div>
            </div>
            {/* ── Analysis History Panel ──────────────────────────────────────── */}
            {(loadingHistory || history.length > 0) && (
                <section className="mt-8">
                    <h2 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
                        <FileText size={18} className="text-orange-400" />
                        Previous Analyses
                    </h2>
                    {loadingHistory ? (
                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                            {[1, 2, 3].map(i => (
                                <div key={i} className="h-24 rounded-2xl bg-white/5 animate-pulse" />
                            ))}
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                            {history.slice(0, 5).map(entry => (
                                <motion.div
                                    key={entry.id}
                                    initial={{ opacity: 0, y: 8 }}
                                    animate={{ opacity: 1, y: 0 }}
                                    className="group relative p-4 rounded-2xl bg-white/5 border border-white/10 hover:border-orange-500/40 hover:bg-white/8 transition-all cursor-pointer"
                                    onClick={() => restoreFromHistory(entry)}
                                    role="button"
                                    aria-label={`Restore analysis from ${new Date(entry.createdAt).toLocaleDateString()} — Score ${entry.score}`}
                                >
                                    <div className="flex items-center justify-between mb-2">
                                        <span className="text-xs text-slate-400">{new Date(entry.createdAt).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}</span>
                                        <span className={`text-sm font-black px-2 py-0.5 rounded-full ${
                                            entry.score >= 80 ? 'bg-emerald-500/20 text-emerald-400' :
                                            entry.score >= 60 ? 'bg-yellow-500/20 text-yellow-400' :
                                            'bg-red-500/20 text-red-400'
                                        }`}>{entry.grade}</span>
                                    </div>
                                    <div className="flex items-baseline gap-1 mb-1">
                                        <span className="text-3xl font-black text-white">{entry.score}</span>
                                        <span className="text-xs text-slate-400">/100</span>
                                    </div>
                                    <p className="text-xs text-slate-500 truncate">{entry.resumeSnippet ?? 'Resume analysis'}</p>
                                    <div className="absolute top-3 right-3 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <span className="text-xs text-orange-400 font-semibold">Restore →</span>
                                    </div>
                                </motion.div>
                            ))}
                        </div>
                    )}
                </section>
            )}
        </div>
    );
}

