'use client';

import { Bot, Send, X, Minimize2, Maximize2, Sparkles } from 'lucide-react';
import { useState, useRef, useEffect } from 'react';

interface Message {
  role: 'user' | 'assistant';
  content: string;
  id: string;
}

interface ChatContext {
  gigTitle?: string;
  gigDescription?: string;
  gigSkills?: string;
  gigBudget?: number;
  studentSkills?: string;
  studentName?: string;
  mode: 'gig-help' | 'career-advice' | 'general';
}

interface AIChatWidgetProps {
  context?: Partial<ChatContext>;
  initialMessage?: string;
  className?: string;
}

const QUICK_PROMPTS = [
  'Write my cover letter',
  'What skills should I highlight?',
  'How do I estimate the timeline?',
  'Help me negotiate the budget',
];

export function AIChatWidget({ context, initialMessage, className }: AIChatWidgetProps) {
  const [open, setOpen] = useState(false);
  const [minimized, setMinimized] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      role: 'assistant',
      content: initialMessage || "Hi! I'm your CampusConnect AI assistant. I can help you write a cover letter, understand gig requirements, estimate timelines, or plan your career. What would you like help with?",
    }
  ]);
  const [input, setInput] = useState('');
  const [streaming, setStreaming] = useState(false);
  const bottomRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const sendMessage = async (text?: string) => {
    const userMessage = (text || input).trim();
    if (!userMessage || streaming) return;

    const userMsg: Message = {
      id: crypto.randomUUID(),
      role: 'user',
      content: userMessage,
    };

    const assistantMsgId = crypto.randomUUID();
    const assistantMsg: Message = {
      id: assistantMsgId,
      role: 'assistant',
      content: '',
    };

    setMessages(prev => [...prev, userMsg, assistantMsg]);
    setInput('');
    setStreaming(true);

    try {
      const chatContext: ChatContext = {
        mode: context?.gigTitle ? 'gig-help' : 'career-advice',
        ...context,
      };

      const res = await fetch('/api/ai/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          messages: [...messages, userMsg].map(m => ({ role: m.role, content: m.content })),
          context: chatContext,
        }),
      });

      if (!res.ok) throw new Error(await res.text());

      const reader = res.body!.getReader();
      const decoder = new TextDecoder();
      let fullContent = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        const chunk = decoder.decode(value, { stream: true });
        const lines = chunk.split('\n').filter(Boolean);

        for (const line of lines) {
          if (line.startsWith('0:')) {
            try {
              const text = JSON.parse(line.slice(2));
              fullContent += text;
              setMessages(prev =>
                prev.map(m =>
                  m.id === assistantMsgId ? { ...m, content: fullContent } : m
                )
              );
            } catch {}
          }
        }
      }
    } catch (err: any) {
      setMessages(prev =>
        prev.map(m =>
          m.id === assistantMsgId
            ? { ...m, content: 'Sorry, something went wrong. Please try again.' }
            : m
        )
      );
    } finally {
      setStreaming(false);
      inputRef.current?.focus();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };

  if (!open) {
    return (
      <button
        onClick={() => setOpen(true)}
        className={`flex items-center gap-2 px-4 py-2.5 bg-linear-to-r from-amber-500 to-orange-500 font-bold rounded-xl shadow-lg hover:shadow-amber-500/20 hover:scale-105 transition-all text-sm ${className}`}
      >
        <Bot className="w-4 h-4" />
        AI Assistant
      </button>
    );
  }

  return (
    <div className={`fixed bottom-6 right-6 z-50 w-[380px] ${className}`}>
      <div className="bg-[#0e0e12] border border-white/10 rounded-2xl shadow-2xl flex flex-col overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between px-4 py-3 border-white/10 bg-linear-to-r from-amber-500/10 to-orange-500/10">
          <div className="flex items-center gap-2">
            <div className="w-7 h-7 rounded-lg bg-(--accent)/20 flex items-center justify-center">
              <Sparkles className="w-4 h-4 text-amber-400" />
            </div>
            <div>
              <p className="text-sm font-black">CampusConnect AI</p>
              <p className="text-slate-500">
                {streaming ? (
                  <span className="text-amber-400 animate-pulse">Typing...</span>
                ) : 'Ask me anything'}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-1">
            <button
              onClick={() => setMinimized(!minimized)}
              className="p-1.5 rounded-lg hover:bg-white/10 transition-colors text-slate-400"
            >
              {minimized ? <Maximize2 className="w-3.5 h-3.5" /> : <Minimize2 className="w-3.5 h-3.5" />}
            </button>
            <button
              onClick={() => setOpen(false)}
              className="p-1.5 hover:bg-white/10 rounded-lg text-slate-400 transition-colors shrink-0"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>

        {!minimized && (
          <>
            {/* Messages */}
            <div className="flex-1 overflow-y-auto p-4 space-y-3 max-h-[360px] min-h-[200px]">
              {messages.map((msg) => (
                <div
                  key={msg.id}
                  className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
                >
                  {msg.role === 'assistant' && (
                    <div className="w-6 h-6 rounded-full bg-(--accent)/20 flex items-center justify-center shrink-0 mt-0.5 mr-2">
                      <Bot className="w-3 h-3 text-amber-400" />
                    </div>
                  )}
                  <div className={`p-3 max-w-[85%] ${msg.role === 'user' ? 'bg-linear-to-r from-orange-500 to-amber-500 ml-auto' : 'bg-white/10 border border-white/5 text-slate-200 rounded-tl-[4px]'}`}>
                    {msg.content || (
                      <span className="flex gap-1 items-center py-1">
                        <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                        <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
                        <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
                      </span>
                    )}
                  </div>
                </div>
              ))}
              <div ref={bottomRef} />
            </div>

            {/* Quick Prompts */}
            {messages.length <= 1 && (
              <div className="px-4 pb-2 flex flex-wrap gap-1.5">
                {QUICK_PROMPTS.map((p) => (
                  <button
                    key={p}
                    onClick={() => sendMessage(p)}
                    className="px-3 py-1.5 bg-(--surface-2) hover:bg-white/10 border border-white/10 rounded-full text-slate-400 hover:text-white transition-all"
                  >
                    {p}
                  </button>
                ))}
              </div>
            )}

            {/* Input */}
            <div className="p-3 border-white/10">
              <div className="flex gap-2 items-end bg-(--surface-2) rounded-xl border border-white/10 px-3 py-2 focus-within:border-amber-500/30 transition-colors">
                <textarea
                  ref={inputRef}
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  onKeyDown={handleKeyDown}
                  placeholder="Ask anything about this gig..."
                  rows={1}
                  className="flex-1 bg-transparent text-slate-200 focus:outline-none resize-none placeholder:text-slate-600 max-h-24"
                  style={{ fieldSizing: 'content' } as any}
                />
                <button
                  onClick={() => sendMessage()}
                  disabled={!input.trim() || streaming}
                  className="w-10 h-10 rounded-xl bg-(--primary) hover:bg-orange-600 text-white flex items-center justify-center shrink-0 disabled:opacity-50 transition-colors shadow-lg"
                >
                  <Send className="w-3.5 h-3.5" />
                </button>
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  );
}


import { Prisma } from "@prisma/client"
import { MapPin, Sparkles, Clock, Users, IndianRupee, ArrowUpRight } from "lucide-react"
import Link from "next/link"


import { calculateDistance, calculateMatchScore } from "@/lib/matching"
import prisma from "@/lib/prisma"
import { createClient } from "@/lib/supabase/server"

import { AICoverLetterButton } from "./AICoverLetterButton"
import { ApplyButton } from "./ApplyButton"



type GigWithPoster = Prisma.GigGetPayload<{
    include: {
        poster: {
            select: { name: true; image: true }
        }
        applications: {
            select: { id: true }
        }
        gigSkills: {
            include: { skill: { select: { name: true; color: true } } }
        }
    }
}>

export async function GigList({ searchParams }: { searchParams?: { q?: string; lat?: string; lng?: string; category?: string } }) {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();

    let dbUser: { skills: string | null; latitude: number | null; longitude: number | null } | null = null;
    if (user) {
        dbUser = await prisma.user.findUnique({
            where: { id: user.id },
            select: { skills: true, latitude: true, longitude: true }
        });
    }

    let gigs: GigWithPoster[] = [];
    try {
        gigs = await prisma.gig.findMany({
            where: {
                status: "OPEN",
                ...(searchParams?.q ? {
                    OR: [
                        { title: { contains: searchParams.q, mode: "insensitive" } },
                        { description: { contains: searchParams.q, mode: "insensitive" } },
                    ]
                } : {})
            },
            include: {
                poster: { select: { name: true, image: true } },
                applications: { select: { id: true } },
                gigSkills: { include: { skill: { select: { name: true, color: true } } } },
            },
            orderBy: { createdAt: 'desc' },
            take: 30,
        });
    } catch (error) {
        console.error("Failed to fetch gigs:", error);
        return (
            <div className="p-8 text-center rounded-2xl border border-red-200 dark:border-red-800 bg-red-50 dark:bg-red-900/20">
                <p className="font-black text-red-700 dark:text-red-400 mb-1">Failed to load gigs</p>
                <p className="text-red-500">Please check your database connection and try again.</p>
            </div>
        )
    }

    if (gigs.length === 0) {
        return (
            <div className="p-16 text-center rounded-2xl border border-slate-200 dark:border-slate-800">
                <div className="w-16 h-16 mx-auto bg-slate-100 dark:bg-slate-800 rounded-2xl flex items-center justify-center mb-4">
                    <Sparkles className="text-slate-400" size={24} />
                </div>
                <h3 className="font-black text-slate-700 dark:text-slate-300 mb-1">No gigs found</h3>
                <p className="text-slate-500">Be the first to post one — or adjust your search.</p>
            </div>
        )
    }

    const parseCoord = (val: string | undefined | null) => {
        if (!val) return null;
        const parsed = parseFloat(val);
        return isNaN(parsed) ? null : parsed;
    };

    const searchLat = parseCoord(searchParams?.lat) ?? dbUser?.latitude;
    const searchLng = parseCoord(searchParams?.lng) ?? dbUser?.longitude;

    const ratedGigs = gigs.map(gig => {
        const distance = (searchLat != null && searchLng != null && gig.latitude != null && gig.longitude != null)
            ? calculateDistance(searchLat as number, searchLng as number, gig.latitude as number, gig.longitude as number)
            : null;
        const matchScore = dbUser ? calculateMatchScore(dbUser.skills, gig.tags) : 0;
        return { ...gig, distance, matchScore };
    });

    if (dbUser) {
        ratedGigs.sort((a, b) => (b.matchScore || 0) - (a.matchScore || 0));
    }

    const daysAgo = (date: Date) => {
        const diff = Math.floor((Date.now() - new Date(date).getTime()) / 86400000);
        return diff === 0 ? "Today" : diff === 1 ? "1d ago" : `${diff}d ago`;
    };

    return (
        <div className="space-y-4">
            <p className="font-bold text-slate-500 dark:text-slate-400">
                <span className="text-slate-900 dark:text-white font-black">{gigs.length}</span> opportunities found
            </p>

            {ratedGigs.map((gig) => (
                <div key={gig.id}
                    className="group relative bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 hover:border-electric/40 hover:shadow-lg transition-all overflow-hidden cursor-pointer">

                    {/* Best Match Banner */}
                    {gig.matchScore > 80 && (
                        <div className="absolute top-0 right-0 bg-electric text-[10px] font-black px-3 py-1.5 rounded-bl-2xl flex items-center gap-1">
                            <Sparkles size={9} /> BEST MATCH
                        </div>
                    )}

                    <div className="flex gap-5">
                        {/* Avatar */}
                        <div className="w-14 h-14 rounded-2xl bg-slate-100 dark:bg-slate-800 shrink-0 flex items-center justify-center font-black text-slate-400 dark:text-slate-500 group-hover:bg-electric/10 group-hover:text-electric transition-colors border border-slate-200 dark:border-slate-700">
                            {gig.poster.name?.[0]?.toUpperCase() || "C"}
                        </div>

                        {/* Content */}
                        <div className="flex-1 min-w-0">
                            <div className="flex items-start justify-between gap-4 mb-2">
                                <div className="min-w-0">
                                    <div className="flex items-center gap-2 flex-wrap mb-1">
                                        <h3 className="font-black text-slate-900 dark:text-white group-hover:text-electric transition-colors truncate">
                                            {gig.title}
                                        </h3>
                                        {gig.matchScore > 0 && (
                                            <span className={`font-black px-2 py-0.5 rounded-full shrink-0 ${gig.matchScore > 60 ? "bg-emerald-100 dark:bg-emerald-900/30 dark:text-emerald-400" : "bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400"}`}>
                                                {gig.matchScore}% Match
                                            </span>
                                        )}
                                    </div>
                                    <div className="flex items-center gap-3 text-slate-500 dark:text-slate-400">
                                        <span className="font-semibold">{gig.poster.name || "Student Poster"}</span>
                                        <span>·</span>
                                        <span>{daysAgo(gig.createdAt)}</span>
                                        {gig.distance && (
                                            <>
                                                <span>·</span>
                                                <span className="flex items-center gap-1"><MapPin size={11} />{gig.distance.toFixed(1)}km away</span>
                                            </>
                                        )}
                                    </div>
                                </div>
                                <div className="shrink-0 flex items-center gap-2">
                                    <AICoverLetterButton gigId={gig.id} gigTitle={gig.title} />
                                    <ApplyButton gigId={gig.id} />
                                </div>
                            </div>

                            {/* Description */}
                            <p className="text-slate-600 dark:text-slate-400 line-clamp-2 mb-4 leading-relaxed">
                                {gig.description}
                            </p>

                            {/* Skills Tags */}
                            {gig.gigSkills.length > 0 && (
                                <div className="flex flex-wrap gap-1.5 mb-4">
                                    {gig.gigSkills.slice(0, 4).map(gs => (
                                        <span key={gs.skillId} className="px-2.5 py-1 rounded-lg font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700">
                                            {gs.skill.name}
                                        </span>
                                    ))}
                                </div>
                            )}

                            {/* Meta row */}
                            <div className="flex items-center flex-wrap gap-4 text-xs">
                                <div className="flex items-center gap-1.5 font-black dark:text-emerald-400 text-sm">
                                    <IndianRupee size={13} />
                                    {gig.budget.toLocaleString()}
                                </div>
                                {gig.deadline && (
                                    <div className="flex items-center gap-1 text-slate-500">
                                        <Clock size={11} />
                                        Due {new Date(gig.deadline).toLocaleDateString("en-IN", { day: "numeric", month: "short" })}
                                    </div>
                                )}
                                <div className="flex items-center gap-1 text-slate-500">
                                    <Users size={11} />
                                    {gig.applications.length} applicant{gig.applications.length !== 1 ? "s" : ""}
                                </div>
                                <div className="ml-auto">
                                    <ArrowUpRight size={16} className="text-slate-300 group-hover:text-electric transition-colors" />
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            ))}
        </div>
    )
}

"use client"

import {
  MessageCircle, Linkedin, Twitter, Instagram,
  X, CheckCircle2, ExternalLink, Copy, Zap
} from "lucide-react"
import Link from "next/link"
import { useState, useEffect, useCallback } from "react"

interface ShareCardModalProps {
  type: string
  userId: string
  onClose: () => void
}

interface CardData {
  template: { headline: string; subtext: string; emoji: string }
  shareUrl: string
  shareText: { whatsapp: string; twitter: string; linkedin: string; instagram: string }
  referralCode: string | null
  userName: string
  college: string
}

const CHANNELS = [
  {
    id: "whatsapp",
    label: "WhatsApp",
    icon: MessageCircle,
    color: "#10B981",
    bg: "rgba(16,185,129,0.12)",
    border: "rgba(16,185,129,0.3)",
    hint: "Highest reach for Indian students",
    recommended: true,
  },
  {
    id: "linkedin",
    label: "LinkedIn",
    icon: Linkedin,
    color: "#0EA5E9",
    bg: "rgba(14,165,233,0.12)",
    border: "rgba(14,165,233,0.3)",
    hint: "Attracts employer attention",
    recommended: false,
  },
  {
    id: "twitter",
    label: "Twitter / X",
    icon: Twitter,
    color: "#64748B",
    bg: "rgba(100,116,139,0.1)",
    border: "rgba(100,116,139,0.2)",
    hint: "Public — indexed by Google",
    recommended: false,
  },
  {
    id: "instagram",
    label: "Instagram Story",
    icon: Instagram,
    color: "#F59E0B",
    bg: "rgba(245,158,11,0.1)",
    border: "rgba(245,158,11,0.25)",
    hint: "Copy caption for your story",
    recommended: false,
  },
] as const

export function ShareCardModal({ type, userId, onClose }: ShareCardModalProps) {
  const [data, setData] = useState<CardData | null>(null)
  const [loading, setLoading] = useState(true)
  const [copied, setCopied] = useState<string | null>(null)

  const fetchCard = useCallback(async () => {
    try {
      const res = await fetch(`/api/growth/share-card?type=${type}&userId=${userId}`)
      if (res.ok) setData(await res.json())
    } finally {
      setLoading(false)
    }
  }, [type, userId])

  useEffect(() => { fetchCard() }, [fetchCard])

  const shareOn = (channel: "whatsapp" | "linkedin" | "twitter" | "instagram") => {
    if (!data) return

    const text = data.shareText[channel]

    const urls: Record<string, string | null> = {
      whatsapp: `https://wa.me/?text=${encodeURIComponent(text)}`,
      linkedin: `https://linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(data.shareUrl)}&summary=${encodeURIComponent(text)}`,
      twitter: `https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}`,
      instagram: null, // Instagram has no web share API — user copies text
    }

    const url = urls[channel]
    if (url) {
      window.open(url, "_blank", "noopener,noreferrer")
    } else {
      // Copy for Instagram
      navigator.clipboard.writeText(text)
      setCopied(channel)
      setTimeout(() => setCopied(null), 2500)
    }
  }

  const copyLink = async () => {
    if (!data) return
    await navigator.clipboard.writeText(data.shareUrl)
    setCopied("link")
    setTimeout(() => setCopied(null), 2500)
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-4"
      style={{ background: "rgba(0,0,0,0.75)", backdropFilter: "blur(6px)" }}
      onClick={e => e.target === e.currentTarget && onClose()}
    >
      <div
        className="w-full max-w-md rounded-3xl overflow-hidden relative"
        style={{ background: "var(--color-surface, #0F1624)", border: "1px solid rgba(255,255,255,0.08)" }}
      >
        {/* Header gradient */}
        <div
          className="p-6 relative overflow-hidden"
          style={{ background: "linear-gradient(135deg, rgba(124,58,237,0.2), rgba(255,69,0,0.12))" }}
        >
          <div className="absolute top-0 right-0 w-32 h-32 blur-3xl rounded-full" style={{ background: "rgba(124,58,237,0.3)" }} />
          <button
            onClick={onClose}
            className="absolute top-4 right-4 w-8 h-8 rounded-xl bg-white/10 flex items-center justify-center hover:bg-white/20 transition-all"
          >
            <X size={14} className="text-slate-300" />
          </button>

          {loading ? (
            <div className="space-y-3 animate-pulse">
              <div className="h-8 bg-white/10 rounded-xl w-3/4" />
              <div className="h-4 bg-white/5 rounded-xl w-1/2" />
            </div>
          ) : data ? (
            <div className="relative z-10">
              <div className="text-4xl mb-2">{data.template.emoji}</div>
              <h2 className="font-black text-white text-base leading-snug mb-1" style={{ fontFamily: "var(--font-display)" }}>
                {data.template.headline}
              </h2>
              <p className="text-sm text-slate-400">{data.template.subtext}</p>
            </div>
          ) : (
            <p className="text-slate-500 text-sm">Could not load share card</p>
          )}
        </div>

        {/* Share channels */}
        <div className="p-5 space-y-3">
          <p className="text-[10px] font-black text-slate-500 uppercase tracking-wider">Share via</p>

          {CHANNELS.map(({ id, label, icon: Icon, color, bg, border, hint, recommended }) => (
            <button
              key={id}
              onClick={() => shareOn(id as "whatsapp" | "linkedin" | "twitter" | "instagram")}
              disabled={!data}
              className="w-full flex items-center justify-between p-3 rounded-2xl transition-all active:scale-[0.98] hover:brightness-110 disabled:opacity-40"
              style={{ background: bg, border: `1px solid ${border}` }}
            >
              <div className="flex items-center gap-3">
                <div className="w-9 h-9 rounded-xl flex items-center justify-center" style={{ background: `${color}20` }}>
                  <Icon size={16} style={{ color }} />
                </div>
                <div className="text-left">
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-black text-white">{label}</span>
                    {recommended && (
                      <span className="text-[9px] font-black px-1.5 py-0.5 rounded-full text-[#10B981] bg-[#10B981]/15 uppercase tracking-wide">
                        Best
                      </span>
                    )}
                  </div>
                  <p className="text-[10px] text-slate-500">{hint}</p>
                </div>
              </div>
              {copied === id ? (
                <CheckCircle2 size={14} className="text-[#10B981]" />
              ) : id === "instagram" ? (
                <Copy size={13} className="text-slate-500" />
              ) : (
                <ExternalLink size={13} className="text-slate-500" />
              )}
            </button>
          ))}

          {/* Direct link */}
          {data && (
            <div className="pt-1">
              <p className="text-[10px] font-black text-slate-600 uppercase tracking-wider mb-2">Or copy your referral link</p>
              <div className="flex items-center gap-2">
                <code className="flex-1 text-[10px] text-slate-400 bg-white/5 rounded-xl px-3 py-2 truncate font-mono">
                  {data.shareUrl}
                </code>
                <button
                  onClick={copyLink}
                  className="shrink-0 px-3 py-2 rounded-xl text-xs font-black flex items-center gap-1 transition-all active:scale-95"
                  style={{
                    background: copied === "link" ? "rgba(16,185,129,0.15)" : "rgba(124,58,237,0.2)",
                    color: copied === "link" ? "#10B981" : "#A78BFA",
                    border: "1px solid rgba(124,58,237,0.25)",
                  }}
                >
                  {copied === "link" ? <CheckCircle2 size={11} /> : <Copy size={11} />}
                  {copied === "link" ? "Copied!" : "Copy"}
                </button>
              </div>
              {data.referralCode && (
                <p className="text-[10px] text-slate-600 mt-1">
                  Referral code: <span className="font-black text-slate-400">{data.referralCode}</span>
                </p>
              )}
            </div>
          )}

          {/* XP nudge */}
          <div
            className="flex items-center gap-3 p-3 rounded-2xl"
            style={{ background: "rgba(124,58,237,0.08)", border: "1px solid rgba(124,58,237,0.15)" }}
          >
            <Zap size={14} className="text-[#7C3AED] shrink-0" />
            <p className="text-xs text-slate-400">
              You and your friend both earn <span className="font-black text-white">100 XP + ₹100</span> when they complete their first gig.
            </p>
          </div>
        </div>
      </div>
    </div>
  )
}

